window.LD=window.LD||{};window.LD["party/p2"]={"id":"p2","name":"The Gravediggers of Ironhaven","poss":"The Gravediggers of Ironhaven's","members":["h8","h15","h2","h11"],"leader":"h8","morale":79,"disposition":"wary","motto":"Back to the wall, eyes on the door.","banner":{"c1":"#7a4cc8","c2":"#e8e8e8","emblem":"skull"},"loc":"sunken_vault","loc_name":"The Sunken Vault","goal":{"text":"to earn 600 silver between them before the season ends","kind":"purse","done":74,"progress":"2,503 silver, past the 600 aimed for","missed":false,"crew":"The Gravediggers of Ironhaven","party":"p2"},"vows":[{"text":"to repay Quill","day":6,"state":"dissolved","ended":6,"through":false,"progress":"dissolved on day 6 of season 1","crew":"The Gravediggers of Ironhaven","party":"p2"},{"text":"never to retreat","day":31,"state":"broken","ended":81,"through":false,"progress":"broken on day 21 of season 3","crew":"The Gravediggers of Ironhaven","party":"p2"}],"doing":"last seen delving into The Sunken Vault","progress":null,"today":["Ate 8 rations.","Used up 7 torches."],"fights_today":[],"why":null,"founded_day":1,"founded_season":1,"disbanded":null,"anthem":{"src":"book","id":"snoring_guard","title":"The Snoring Guard","tone":"funny","meter":"4/4","bpm":109,"diff":2,"day":35,"night":null,"n":7,"by":null,"lead":{"id":"h8","name":"Hazel","skill":0.462,"inst":"flute"}},"renown":311,"season":{"wins":8,"bosses":0,"floors":8,"gold":0,"deaths":0,"fled":1,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":30,"arguments":2},"career":{"wins":27,"bosses":1,"floors":24,"gold":0,"deaths":0,"fled":2,"pvp_wins":0,"pvp_losses":0,"renown":0,"days":90,"arguments":6},"former":[],"fallen":[],"travel":null,"wagon":null,"pace_gap":48,"rels":[{"party":"p3","score":100},{"party":"p6","score":55},{"party":"p5","score":21},{"party":"p1","score":20},{"party":"p4","score":2}],"events":[{"id":"e872","day":25,"season":1,"sday":25,"kind":"road","imp":2,"text":"Hetty Brimble is polishing a lantern glass with her apron when Quill comes by for the first time. She holds it up so Quill can admire how clear it is.","heroes":["h11","h15","h2","h8"],"parties":["p2"],"road":"ashfen~ashveil_crypts","traveller":"hetty","road_rec":"r187"},{"id":"e887","day":25,"season":1,"sday":25,"kind":"campfire","imp":1,"text":"Sela and Rook discover they grew up three valleys apart. The conversation lasts longer than either expected.","heroes":["h2","h15"],"parties":["p2"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e896","day":26,"season":1,"sday":26,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into the Ashveil Crypts, mostly explored (75%), map in hand.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e939","day":27,"season":1,"sday":27,"kind":"delve_done","imp":1,"text":"The Ashveil Crypts hands The Gravediggers of Ironhaven back after 2 days, dusty and squinting. They went as deep as the place goes and turned back because they were down to the last torch.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"ashveil_crypts","days":2,"bottom":true,"rooms":[],"gold":0,"turn":"dark","wx":"fog"},{"id":"e951","day":27,"season":1,"sday":27,"kind":"campfire","imp":3,"text":"Hazel asks Rook how Armorers and Elementalists are supposed to work together. Neither knows. They work it out.","heroes":["h8","h15"],"parties":["p2"],"loc":"ashveil_crypts","wx":"fog"},{"id":"e987","day":28,"season":1,"sday":28,"kind":"ledger","imp":2,"text":"MARKET WEEK: 14 hauls sold across the realm, 1,072 silver all told. Biggest haul: Brix, 284 silver in Carrbridge. Back up from the deep: The Gravediggers of Ironhaven (3 days in the Ashveil Crypts), The Lantern of Carrbridge (3 days in the Ashveil Crypts).","heroes":["h1","h8","h4"],"parties":["p2","p1"]},{"id":"e1001","day":29,"season":1,"sday":29,"kind":"party_life","imp":3,"text":"Rook and Quill spend the whole road in the dust Hazel and Sela kick up, and say so.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"ashfen","wx":"fog"},{"id":"e1002","day":29,"season":1,"sday":29,"kind":"talent","imp":2,"text":"Hazel loses the first hand on purpose to see how Quill deals. The rest of the evening goes better.","heroes":["h8","h11"],"parties":["p2"],"loc":"bleakmarsh","skill":"gambit","wx":"fog"},{"id":"e1017","day":30,"season":1,"sday":30,"kind":"talent","imp":1,"text":"Quill lies down in the grass and the grass, very gently, holds them there till morning.","heroes":["h11"],"parties":["p2"],"loc":"thornmere_ruins","skill":"rootbound_ground","wx":"fog"},{"id":"e1028","day":30,"season":1,"sday":30,"kind":"meet","imp":1,"text":"The Gravediggers of Ironhaven run into Cobalt Mercy in Thornmere Ruins. Stories are exchanged, most of them exaggerated.","heroes":["h8","h15","h2","h11","h19","h20"],"parties":["p2","p6"],"loc":"thornmere_ruins","wx":"fog"},{"id":"e1029","day":30,"season":1,"sday":30,"kind":"journey","imp":3,"text":"The Gravediggers of Ironhaven and The Lantern of Carrbridge share the road to Thornmere Ruins. By the second milestone they've agreed on nothing, least of all Quill's terrible singing.","heroes":["h8","h15","h2","h11","h4","h18","h12"],"parties":["p2","p1"]},{"id":"e1077","day":31,"season":2,"sday":1,"kind":"party_life","imp":3,"text":"Hazel and Sela ride ahead, ride back, ride ahead again. Rook and Quill are not amused.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"veldrock","wx":"snow"},{"id":"e1078","day":31,"season":2,"sday":1,"kind":"road","imp":3,"text":"Bodkin shows Hazel how to temper a nail at the fire. Hazel makes three crooked ones and a fourth that holds.","heroes":["h8","h11","h15","h2"],"parties":["p2"],"road":"redcrag~veldrock","traveller":"kettleby","road_rec":"r229"},{"id":"e1079","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Sela teaches Quill the sign for 'tea'. Quill now uses it constantly.","heroes":["h2","h11"],"parties":["p2"],"loc":"redcrag","skill":"hand_signs"},{"id":"e1080","day":31,"season":2,"sday":1,"kind":"night","imp":2,"text":"Sela follows strange lights away from the camp in Redcrag Hills, gets thoroughly lost, and is found at dawn up a tree.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"redcrag"},{"id":"e1082","day":31,"season":2,"sday":1,"kind":"boss_race","imp":3,"text":"The Mimic King's Ghost has visitors coming. The Gravediggers of Ironhaven, Azure Edge and The Tidal Almanac are all on the way to Cragtooth Warren, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h3","h9","h1","h5","h10","h14","h16"],"parties":["p2","p3","p4"],"loc":"cragtooth_warren"},{"id":"e1099","day":31,"season":2,"sday":1,"kind":"campfire","imp":1,"text":"Hazel and Rook see in a month of The Gravediggers of Ironhaven by splitting the last good bottle. Nobody else is offered any.","heroes":["h8","h15"],"parties":["p2"],"loc":"redcrag"},{"id":"e1101","day":31,"season":2,"sday":1,"kind":"talent","imp":1,"text":"Quill lights the campfire by breathing on it. Hazel has seen this forty times and still claps. Fire Eater: one of the things Quill learned the long way round.","heroes":["h11","h8"],"parties":["p2"],"loc":"redcrag","skill":"fire_eater"},{"id":"e1109","day":31,"season":2,"sday":1,"kind":"vow","imp":3,"text":"A vow from The Gravediggers of Ironhaven: never to retreat. Easy to say on day one.","heroes":["h8","h15","h2","h11"],"parties":["p2"]},{"id":"e1121","day":32,"season":2,"sday":2,"kind":"party_life","imp":1,"text":"By the third crossroads Hazel and Sela have stopped waiting and started complaining about the wait.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"redcrag","wx":"rain"},{"id":"e1122","day":32,"season":2,"sday":2,"kind":"talent","imp":1,"text":"Rook boils the kettle, chills the milk and dries the towels before Quill has found the cups.","heroes":["h15","h11"],"parties":["p2"],"loc":"cragtooth_warren","skill":"all_three_at_once","wx":"rain"},{"id":"e1123","day":32,"season":2,"sday":2,"kind":"night","imp":2,"text":"Hazel trades a ration with a stranger who wasn't there at dusk and isn't there at dawn. The trinket stays.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e1132","day":32,"season":2,"sday":2,"kind":"ability","imp":2,"text":"Sela finds a library in Cragtooth Warren that the monsters have been using as a larder. She rescues the one readable shelf and comes out an expert on old drains, and calmer for it.","heroes":["h2"],"parties":["p2"],"loc":"cragtooth_warren","skill":"walking_library","sk":"Walking Library","rule":true,"wx":"rain"},{"id":"e1152","day":33,"season":2,"sday":3,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into Cragtooth Warren, untouched (0%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e1153","day":33,"season":2,"sday":3,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Cragtooth Warren at a steady pace: 5 rooms (the first run, the prospectors' bunkhouse, the sleeping burrows and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":5,"size":4,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]},"wx":"rain"},{"id":"e1162","day":33,"season":2,"sday":3,"kind":"talent","imp":2,"text":"Rook lights the room, freezes the puddle and sparks the rusty lever, all in one gesture. All Three at Once, the guild calls it.","heroes":["h15"],"parties":["p2"],"loc":"cragtooth_warren","skill":"all_three_at_once","wx":"rain"},{"id":"e1165","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"Thirty days in The Gravediggers of Ironhaven. Hazel and Sela have stopped keeping score of who owes whom.","heroes":["h8","h2"],"parties":["p2"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e1166","day":33,"season":2,"sday":3,"kind":"campfire","imp":1,"text":"A month together in The Gravediggers of Ironhaven, and Rook has finally learned Sela's middle name. There are three. It's a long story.","heroes":["h15","h2"],"parties":["p2"],"loc":"cragtooth_warren","wx":"rain"},{"id":"e1180","day":34,"season":2,"sday":4,"kind":"fight","imp":2,"text":"Two Kobold Slingers, a Giant Bat and a Kobold fall to the Gravediggers of Ironhaven in the sentry hole on floor 1 of Cragtooth Warren. Sela cast Arcane Torrent into the middle of them, and four of them didn't get up. Loot: 5 silver each, 1 fang, a pair of bat wings.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","fight":"f75","foes":["giant_bat","kobold_slinger","kobold"],"where":"in the sentry hole on floor 1 of Cragtooth Warren","won":true,"close":false,"shape":"foe","reworded":-2},{"id":"e1182","day":34,"season":2,"sday":4,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Cragtooth Warren at a steady pace: 5 rooms (the drain cut, the sentry hole, the dry store and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":5,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["cosmetic"],"fears":1,"wild":[]}},{"id":"e1189","day":34,"season":2,"sday":4,"kind":"meet","imp":2,"text":"Azure Edge and The Gravediggers of Ironhaven share a fire in Cragtooth Warren and trade news.","heroes":["h3","h9","h1","h5","h8","h15","h2","h11"],"parties":["p3","p2"],"loc":"cragtooth_warren"},{"id":"e1212","day":35,"season":2,"sday":5,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Cragtooth Warren at a steady pace: 1 room (a chute with chewed footholds).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":1,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1223","day":35,"season":2,"sday":5,"kind":"music","imp":2,"text":"The Gravediggers of Ironhaven have adopted \"The Snoring Guard\", and have started making up extra verses about each other.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","anthem":"snoring_guard","night":"n63"},{"id":"e1238","day":36,"season":2,"sday":6,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Cragtooth Warren at a steady pace: 1 room (a chute with chewed footholds).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","pace":"steady","stats":{"rooms":1,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e1239","day":36,"season":2,"sday":6,"kind":"delve_done","imp":3,"text":"After 4 days underground, The Gravediggers of Ironhaven climb back into the open air, gulping it down like water. They reached floor 1, took 10 rooms off the map's blank side, took the teeth out of 1 trap, mapped 27% of it, found the stolen-goods bin and the hoard-sorting cave, came away with 54 silver between them and turned back because the way on beat them twice, and they mean to come back with more. The guild's map has it: Cragtooth Warren is partly explored (35%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","days":4,"bottom":false,"rooms":["the stolen-goods bin","the hoard-sorting cave"],"gold":54,"turn":"blocked"},{"id":"e1254","day":36,"season":2,"sday":6,"kind":"boss_race","imp":2,"text":"The Gravediggers of Ironhaven drop out of the race for The Mimic King's Ghost. That leaves Azure Edge and The Tidal Almanac in it.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e1257","day":36,"season":2,"sday":6,"kind":"campfire","imp":2,"text":"Hazel and Quill, a month into The Gravediggers of Ironhaven: they walk in step now without trying.","heroes":["h8","h11"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e1259","day":36,"season":2,"sday":6,"kind":"campfire","imp":1,"text":"A month in The Gravediggers of Ironhaven: Rook could pick Quill's footsteps out of a crowd now.","heroes":["h15","h11"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e1260","day":36,"season":2,"sday":6,"kind":"campfire","imp":3,"text":"A month in The Gravediggers of Ironhaven together. Sela and Quill know each other's snores, sorrows and orders by heart.","heroes":["h2","h11"],"parties":["p2"],"loc":"cragtooth_warren"},{"id":"e1283","day":37,"season":2,"sday":7,"kind":"party_life","imp":1,"text":"Hazel and Sela wait at every crossroads for Rook and Quill to catch up, and say nothing very loudly.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"cragtooth_warren","wx":"storm"},{"id":"e1285","day":37,"season":2,"sday":7,"kind":"gift","imp":2,"text":"Nothing goes to waste in this crew: Sela's old Traveling Cloak is Quill's now.","heroes":["h2","h11"],"parties":["p2"],"loc":"ironhaven","wx":"storm"},{"id":"e1321","day":38,"season":2,"sday":8,"kind":"party_life","imp":3,"text":"Rook and Quill ask Hazel and Sela if the view is nice up there. It is.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"ironhaven","wx":"storm"},{"id":"e1322","day":38,"season":2,"sday":8,"kind":"road","imp":3,"text":"Lady Perpetua Vane is certain the fork to the left is correct. Hazel says nothing, and an hour later she says 'a most scenic detour'.","heroes":["h8","h11","h15","h2"],"parties":["p2"],"road":"carrbridge~ironhaven","traveller":"perpetua","road_rec":"r266"},{"id":"e1349","day":38,"season":2,"sday":8,"kind":"boss_race","imp":3,"text":"Mother Thornmere has visitors coming. The Gravediggers of Ironhaven and The White Quills are both on the way to Thornmere Ruins, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h7","h13"],"parties":["p2","p5"],"loc":"thornmere_ruins"},{"id":"e1350","day":38,"season":2,"sday":8,"kind":"talent","imp":2,"text":"Hazel trades a Carrbridge baker a sourdough starter for a sack of flour. The baker's eyes light up. (Trail Baker, if anyone's asking.)","heroes":["h8"],"parties":["p2"],"loc":"carrbridge","skill":"trail_baker","wx":"storm"},{"id":"e1362","day":39,"season":2,"sday":9,"kind":"raid","imp":5,"text":"Carrbridge is attacked at dusk by swamp trolls out of Thornmere Ruins, and Sela, Hazel, Quill and Rook hold the gate. The town pays the defenders 25 silver each, and nobody in Carrbridge will buy their own drink tonight.","heroes":["h2","h8","h11","h15"],"parties":["p2"],"loc":"carrbridge","fight":"f94"},{"id":"e1363","day":39,"season":2,"sday":9,"kind":"song","imp":3,"text":"A travelling bard at The Honest Toll has a new song: \"The Night of the Swamp Trolls\". The chorus is already stuck in everyone's head.","heroes":["h2","h8","h11","h15"],"parties":["p2"],"loc":"carrbridge","song":"s39_15"},{"id":"e1390","day":39,"season":2,"sday":9,"kind":"ambush","imp":3,"text":"On the road to Bleakmarsh, 2 Bog Crawlers, a Giant Spider and a Swamp Troll get in the Gravediggers of Ironhaven's way, briefly. The bog-things had been driving the troll toward the road for an hour. The Gravediggers of Ironhaven happened to be in the way. The fight was over the moment Hazel's Anvil Drop landed on the bog crawler. Quill's Entangle turned the fight. Sela stopped to read the writing on the walls and is now worried about it. \"Write down the date. It matters,\" says Sela. Loot: 11 silver each, 4 chitin, 4 bog crawler claws.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"bleakmarsh","fight":"f97","foes":["bog_crawler","bog_crawler","giant_spider"],"where":"on the road to Bleakmarsh","won":true,"close":false,"shape":"place","reworded":-15},{"id":"e1391","day":39,"season":2,"sday":9,"kind":"talent","imp":1,"text":"Quill brews something green and bitter for Hazel's cough. Hazel hates it. The cough's gone by morning. Somebody asks how. 'Herbalism,' says Quill.","heroes":["h11","h8"],"parties":["p2"],"loc":"bleakmarsh","skill":"herbalism"},{"id":"e1431","day":40,"season":2,"sday":10,"kind":"meet","imp":2,"text":"The White Quills and The Gravediggers of Ironhaven share a fire in Thornmere Ruins. Bramble shares directions.","heroes":["h7","h13","h8","h15","h2","h11"],"parties":["p5","p2"],"loc":"thornmere_ruins"},{"id":"e1458","day":41,"season":2,"sday":11,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into Thornmere Ruins, partly explored (59%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1471","day":41,"season":2,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Gravediggers of Ironhaven settle on a goal: to find a relic of the old world.","heroes":["h8","h15","h2"],"parties":["p2"]},{"id":"e1495","day":42,"season":2,"sday":12,"kind":"gear","imp":1,"text":"In a sealed space off the drowned crypt on floor 3 of Thornmere Ruins, Quill finds a Sturdy Riveted Belt and puts it on. Sturdy: a little better protected (+1.5 armour).","heroes":["h11"],"parties":["p2"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1496","day":42,"season":2,"sday":12,"kind":"wild_room","imp":3,"text":"Rook's fear of water finds a dry stair in Thornmere Ruins. Rook: 'I've been saying this for years.'","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","room":"wild_cowards_stair","wx":"storm"},{"id":"e1497","day":42,"season":2,"sday":12,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 3 of Thornmere Ruins at a push pace: 4 rooms (the poor box, the drowned crypt, a sealed space off the drowned crypt and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","pace":"push","stats":{"rooms":4,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":0,"close":0,"gear":["common","great"],"fears":2,"wild":["wild_cowards_stair"]},"wx":"storm"},{"id":"e1503","day":42,"season":2,"sday":12,"kind":"meet","imp":2,"text":"The Gravediggers of Ironhaven warn Azure Edge about what's lurking in Thornmere Ruins. Azure Edge pretends to already know.","heroes":["h8","h15","h2","h11","h3","h9","h1","h5"],"parties":["p2","p3"],"loc":"thornmere_ruins","wx":"storm"},{"id":"e1512","day":42,"season":2,"sday":12,"kind":"argument","imp":2,"text":"Sela and Rook of The Gravediggers of Ironhaven have a shouting match about the party's name.","heroes":["h2","h15"],"parties":["p2"]},{"id":"e1527","day":43,"season":2,"sday":13,"kind":"fight","imp":2,"text":"Hazel keeps everyone up as the Gravediggers of Ironhaven see off 3 Swamp Trolls and 2 Sirens in the reed stair on floor 3 of Thornmere Ruins. Sela's Arcane Torrent lit up five of them together. Hazel's Cavalry Drill kicked in when it counted. Loot: 22 silver each, 6 troll hide, 1 gem. Rook hates deep water more than anything, and fights through it anyway.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f101","foes":["swamp_troll","siren","siren"],"where":"in the reed stair on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"hero","reworded":-27,"wx":"rain"},{"id":"e1529","day":43,"season":2,"sday":13,"kind":"fight","imp":2,"text":"The Gravediggers of Ironhaven beat 2 Sirens and 2 Bog Crawlers in the singing sump on floor 3 of Thornmere Ruins. One Arc Lightning from Quill and three of them were on the ground. Rook pulled a friend out of trouble and went back in for more. Loot: 4 trinkets, 2 chitin, 2 bog crawler claws.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f102","foes":["siren","bog_crawler","siren"],"where":"in the singing sump on floor 3 of Thornmere Ruins","won":true,"close":false,"shape":"plain","wx":"rain"},{"id":"e1530","day":43,"season":2,"sday":13,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 3 of Thornmere Ruins at a steady pace: 4 rooms (the lantern rack, the reed stair, the confession box and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","pace":"steady","stats":{"rooms":4,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":["common","common"],"fears":2,"wild":[]},"wx":"rain"},{"id":"e1540","day":43,"season":2,"sday":13,"kind":"gift","imp":2,"text":"Sela gives Quill a Third-Place Ribbon. \"For luck,\" Sela says, and won't explain further.","heroes":["h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","wx":"rain"},{"id":"e1542","day":43,"season":2,"sday":13,"kind":"talent","imp":1,"text":"Sela gets a fire going at Thornmere Ruins from a broken chair and some goblin bedding. It burns blue and smells odd but it's warm.","heroes":["h2"],"parties":["p2"],"loc":"thornmere_ruins","skill":"firekeeper","wx":"rain"},{"id":"e1555","day":44,"season":2,"sday":14,"kind":"gear","imp":1,"text":"In a sealed space off the singing sump on floor 3 of Thornmere Ruins, Sela finds a Fen-Proofed Shark-Tooth Necklace and puts it on. Fen-Proofed: tougher (+4% health).","heroes":["h2"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e1561","day":44,"season":2,"sday":14,"kind":"boss","imp":5,"text":"Mother Thornmere, a Swamp Troll and a Drake have held the bottom of Thornmere Ruins long enough: the Gravediggers of Ironhaven put an end to them. All Three at Once from Rook left the swamp troll reeling. Hazel's Cavalry Drill came at the right time for all of them. Sela landed 3 crushing blows, mostly with Chill Touch. Entangle, from Quill, at exactly the right moment. Loot: 149 silver each, 15 moonpetal, 10 bottled wisplight.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","fight":"f103","foes":["hag_mother","swamp_troll","drake"],"where":"at the bottom of Thornmere Ruins","won":true,"close":false,"shape":"foe","reworded":-34},{"id":"e1562","day":44,"season":2,"sday":14,"kind":"treasure","imp":2,"text":"Sorting through what Mother Thornmere left behind turns up 15 gold pieces and 2 silver, a lot of old bones and one good spoon.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","in_fight":"f103"},{"id":"e1563","day":44,"season":2,"sday":14,"kind":"sniped","imp":3,"text":"Thornmere Ruins is quieter now, because The Gravediggers of Ironhaven killed Mother Thornmere today, and The Lantern of Carrbridge and Azure Edge all hear it by noon and change their plans to suit.","heroes":["h1","h11","h12","h15","h18","h2","h3","h4","h5","h8","h9"],"parties":["p1","p2","p3"],"loc":"thornmere_ruins","snipers":["h8","h15","h2","h11"],"where":"many","boss":"Mother Thornmere","in_fight":"f103"},{"id":"e1564","day":44,"season":2,"sday":14,"kind":"race_won","imp":1,"text":"The Gravediggers of Ironhaven win the race to Mother Thornmere, ahead of The Lantern of Carrbridge and Azure Edge. The bets are paid out in Carrbridge before the blood is dry.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","in_fight":"f103"},{"id":"e1565","day":44,"season":2,"sday":14,"kind":"gear","imp":4,"text":"A knot of hair and reed on a cord from the Hag Mother's nest leaves the dark of Thornmere Ruins in Hazel's pack. There isn't another. What it can do is anyone's guess until a town names it.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e1566","day":44,"season":2,"sday":14,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 3 of Thornmere Ruins at a cautious pace: 3 rooms (a sealed space off the singing sump, the curtain of hair, the Hag Mother's nest).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","pace":"cautious","stats":{"rooms":3,"size":4,"floor":3,"traps":1,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great","unique"],"fears":0,"wild":[]}},{"id":"e1567","day":44,"season":2,"sday":14,"kind":"delve_done","imp":3,"text":"The Gravediggers of Ironhaven climb out at last, 4 days older and a good deal dirtier. They worked through 11 rooms, went as deep as the place goes, inked 23% of the map, came across the poor box, a sealed space off the drowned crypt, the lantern rack and 4 more good rooms, took the teeth out of 1 trap and split 1256 silver on the way up. Add up every party's sketches and Thornmere Ruins comes out mostly explored (78%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins","days":4,"bottom":true,"rooms":["the poor box","a sealed space off the drowned crypt"],"gold":1256,"turn":"done"},{"id":"e1584","day":44,"season":2,"sday":14,"kind":"talent","imp":2,"text":"Sela recognises the carvings on a door and opens it with the right word. Chalk it up to Walking Library.","heroes":["h2"],"parties":["p2"],"loc":"thornmere_ruins","skill":"walking_library"},{"id":"e1593","day":44,"season":2,"sday":14,"kind":"goal_done","imp":4,"text":"GOAL: The Gravediggers of Ironhaven set out to find a relic of the old world, and they have done it, with 16 days to spare. Hazel found it. XP: Hazel +960 (level 17!), Rook +800 (level 16!), Sela +1104 (level 18!), Quill +960 (level 16!).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"xp":{"h8":960,"h15":800,"h2":1104,"h11":960}},{"id":"e1598","day":44,"season":2,"sday":14,"kind":"big_move","imp":4,"text":"Mother Thornmere, a Swamp Troll and a Drake have held the bottom of Thornmere Ruins long enough: the Gravediggers of Ironhaven put an end to them. On the table: Quill +135 renown (12th to 2nd), Sela +135 (11th to 1st), Hazel +134 (13th to 3rd) and Rook +129 (10th to 4th). The Gravediggers of Ironhaven +231 party renown (3rd to 1st among the crews).","heroes":["h11","h2","h8","h15"],"parties":["p2"],"cause":"e1561","moves":[{"hero":"h11","gain":135,"from":12,"to":2},{"hero":"h2","gain":135,"from":11,"to":1},{"hero":"h8","gain":134,"from":13,"to":3},{"hero":"h15","gain":129,"from":10,"to":4}],"party_moves":[{"party":"p2","gain":231,"from":3,"to":1}],"fight":"f103"},{"id":"e1610","day":45,"season":2,"sday":15,"kind":"party_life","imp":3,"text":"Rook and Quill arrive at camp an hour behind Hazel and Sela and find the good spot by the fire taken.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"thornmere_ruins"},{"id":"e1611","day":45,"season":2,"sday":15,"kind":"talent","imp":1,"text":"Sela banks the fire so there are still coals at dawn. Breakfast is twenty minutes sooner. That's Firekeeper for you.","heroes":["h2"],"parties":["p2"],"loc":"bleakmarsh","skill":"firekeeper"},{"id":"e1635","day":46,"season":2,"sday":16,"kind":"party_life","imp":3,"text":"Rook and Quill arrive at camp an hour behind Hazel and Sela and find the good spot by the fire taken.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"bleakmarsh"},{"id":"e1651","day":46,"season":2,"sday":16,"kind":"talent","imp":1,"text":"Quill finds a Carrbridge weed growing through the cobbles and quietly encourages it.","heroes":["h11"],"parties":["p2"],"loc":"carrbridge","skill":"rootbound_ground"},{"id":"e1668","day":47,"season":2,"sday":17,"kind":"road","imp":3,"text":"Sela nudges a boundary stone a few handspans on the road to Ironhaven when no one is looking, and later a grateful farmer leaves a gem at the roadside.","heroes":["h2","h11","h15","h8"],"parties":["p2"],"road":"carrbridge~ironhaven","road_rec":"r325"},{"id":"e1696","day":47,"season":2,"sday":17,"kind":"argument","imp":1,"text":"The Gravediggers of Ironhaven spend the evening listening to Quill and Rook argue about whether ghosts can be bribed.","heroes":["h11","h15"],"parties":["p2"]},{"id":"e1711","day":48,"season":2,"sday":18,"kind":"party_life","imp":1,"text":"Hazel and Sela ride ahead, ride back, ride ahead again. Rook and Quill are not amused.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"ironhaven"},{"id":"e1712","day":48,"season":2,"sday":18,"kind":"road","imp":3,"text":"Quill trades a verse for a chorus with Teodor over a campfire. A whole song is in the world that was not there at breakfast.","heroes":["h11","h15","h2","h8"],"parties":["p2"],"road":"frosthold~ironhaven","traveller":"teodor","road_rec":"r338"},{"id":"e1771","day":50,"season":2,"sday":20,"kind":"road","imp":3,"text":"A pedlar on the road to Whitepeak Pass has a bone flute with a split in it. Hazel binds the crack with waxed thread, and the flute plays again. The pedlar presses it into her hands.","heroes":["h8","h11","h15","h2"],"parties":["p2"],"road":"frosthold~whitepeak","road_rec":"r355"},{"id":"e1775","day":50,"season":2,"sday":20,"kind":"talent","imp":1,"text":"Hazel hands Sela a cup at a roadside halt and doesn't ask what's wrong. Sela says anyway. That's Tea Ceremony for you.","heroes":["h8","h2"],"parties":["p2"],"loc":"whitepeak","skill":"tea_ceremony","wx":"snow"},{"id":"e1811","day":51,"season":2,"sday":21,"kind":"ability","imp":2,"text":"A riddle is carved over a door in Frostspire. Sela answers it, then corrects its spelling. The door opens anyway, and Sela is in a very good mood for the rest of the day.","heroes":["h2"],"parties":["p2"],"loc":"frostspire","skill":"walking_library","sk":"Walking Library","rule":true,"wx":"snow"},{"id":"e1815","day":51,"season":2,"sday":21,"kind":"campfire","imp":1,"text":"Quill mends Rook's bootlace with a bit of string and a great deal of confidence.","heroes":["h11","h15"],"parties":["p2"],"loc":"frostspire","wx":"snow"},{"id":"e1837","day":52,"season":2,"sday":22,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into Frostspire, mostly unexplored (11%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","wx":"snow"},{"id":"e1838","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"In the hall of blue ice on floor 1 of Frostspire, the Gravediggers of Ironhaven square up to 3 Ice Wraiths and a Frost Wolf and carry the day. Sela's Arcane Torrent took most of the fight out of the ice wraith in one go. Rook accounted for 3 of them, mostly with Spark Storm. Loot: 2 frost crystals, 3 ectoplasm, 3 pelts. Quill, who has been afraid of the cold since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","fight":"f126","foes":["ice_wraith","ice_wraith","ice_wraith"],"where":"in the hall of blue ice on floor 1 of Frostspire","won":true,"close":false,"shape":"place","reworded":-13,"wx":"snow"},{"id":"e1840","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"The Gravediggers of Ironhaven, in fine spirits lately, make short work of 2 Yetis and 2 Ice Wraiths in a ladder of frozen rope hanging in a shaft, climbing into mist on floor 1 of Frostspire. Quill's Arc Lightning finished the fight. Loot: 15 pelts, 3 ectoplasm, 3 yeti steaks.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","fight":"f127","foes":["yeti","ice_wraith","yeti"],"where":"in a ladder of frozen rope hanging in a shaft, climbing into mist on floor 1 of Frostspire","won":true,"close":false,"shape":"mood","reworded":-25,"wx":"snow"},{"id":"e1842","day":52,"season":2,"sday":22,"kind":"fight","imp":2,"text":"The Gravediggers of Ironhaven see off 2 Ice Golems and an Ice Wraith in the frozen guardroom on floor 1 of Frostspire without much fuss. Hazel's Cavalry Drill came at the right time for all of them. Loot: 7 frost crystals.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","fight":"f128","foes":["ice_golem","ice_wraith","ice_golem"],"where":"in the frozen guardroom on floor 1 of Frostspire","won":true,"close":false,"shape":"plain","reworded":-18,"wx":"snow"},{"id":"e1843","day":52,"season":2,"sday":22,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Frostspire at a push pace: 4 rooms (the hall of blue ice, the lens hall, a ladder of frozen rope hanging in a shaft, climbing into mist and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"push","stats":{"rooms":4,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":3,"close":0,"gear":[],"fears":4,"wild":[]},"wx":"snow"},{"id":"e1869","day":53,"season":2,"sday":23,"kind":"wild_room","imp":3,"text":"A Frostspire yeti has asked, through a series of gestures, for Sela's recipe.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","room":"wild_yeti_supper"},{"id":"e1870","day":53,"season":2,"sday":23,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Frostspire at a steady pace: 4 rooms (the sentry stair, the yeti's empty pot, the clear-ice room and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"steady","stats":{"rooms":4,"size":4,"floor":1,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":1,"wild":["wild_yeti_supper"]}},{"id":"e1871","day":53,"season":2,"sday":23,"kind":"night","imp":2,"text":"Something small and clever gets into The Gravediggers of Ironhaven's camp on floor 1 of Frostspire overnight. Sela wakes up 4 silver and 2 rations lighter.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire"},{"id":"e1917","day":54,"season":2,"sday":24,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of Frostspire at a push pace: 5 rooms (the meltwater seep, the ice-locked armoury, the yeti's nest of shinies and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"push","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e1949","day":55,"season":2,"sday":25,"kind":"gear","imp":1,"text":"In a walled-up room beside the sentries' bunks on floor 2 of Frostspire, Sela finds a Sturdy Shadowweave Hood and puts it on. Sturdy: a little better protected (+1.5 armour).","heroes":["h2"],"parties":["p2"],"loc":"frostspire"},{"id":"e1950","day":55,"season":2,"sday":25,"kind":"fight","imp":3,"text":"It's 2 Frost Wolves and 2 Yetis against the Gravediggers of Ironhaven in the yeti's meat hall on floor 2 of Frostspire, and it isn't close. Rook had the last word, and the word was All Three at Once. Without Quill's Entangle, this goes differently. Loot: 19 pelts, 9 fangs & claws, 4 wolf haunches.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","fight":"f136","foes":["frost_wolf","frost_wolf","yeti"],"where":"in the yeti's meat hall on floor 2 of Frostspire","won":true,"close":false,"shape":"foe","reworded":-25},{"id":"e1951","day":55,"season":2,"sday":25,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of Frostspire at a steady pace: 5 rooms (a walled-up room beside the sentries' bunks, the chamber of perfect carvings, the yeti's nest of shinies and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"steady","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["great","common"],"fears":1,"wild":[]}},{"id":"e1952","day":55,"season":2,"sday":25,"kind":"boss_race","imp":3,"text":"Hrimnir, Who Walks Under Snow has visitors coming. The Gravediggers of Ironhaven and Tobias are both on the way to Frostspire, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h6"],"parties":["p2"],"loc":"frostspire"},{"id":"e1971","day":56,"season":2,"sday":26,"kind":"fight","imp":2,"text":"Sela hits hardest as the Gravediggers of Ironhaven defeat 2 Yetis and 2 Frost Wolves in the yeti dens on floor 2 of Frostspire. The last frost wolf bolts. That Arcane Torrent from Sela was the moment it tipped. Loot: 19 pelts, 1 frost crystal, 6 yeti steaks.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","fight":"f137","foes":["yeti","frost_wolf","frost_wolf"],"where":"in the yeti dens on floor 2 of Frostspire","won":true,"close":false,"shape":"hero","reworded":-21},{"id":"e1972","day":56,"season":2,"sday":26,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of Frostspire at a cautious pace: 4 rooms (a hidden room behind the golem's niche, the yeti dens, a ladder of frozen rope hanging in a shaft, climbing into mist and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"cautious","stats":{"rooms":4,"size":4,"floor":2,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":["common"],"fears":2,"wild":[]}},{"id":"e1973","day":56,"season":2,"sday":26,"kind":"talent","imp":1,"text":"Rook knocks a pine cone off a branch in the dark, by sound alone. Sela demands to see it again. Trick Shot: a ranger's patience, mostly.","heroes":["h15","h2"],"parties":["p2"],"loc":"frostspire","skill":"trick_shot"},{"id":"e1996","day":56,"season":2,"sday":26,"kind":"ability","imp":2,"text":"Halfway down Frostspire, Sela spots an inscription everyone else took for scratches. Twenty minutes of happy muttering later, they are noticeably cleverer.","heroes":["h2"],"parties":["p2"],"loc":"frostspire","skill":"walking_library","sk":"Walking Library","rule":true},{"id":"e2014","day":57,"season":2,"sday":27,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of Frostspire at a steady pace: 1 room (the draught hole).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2015","day":57,"season":2,"sday":27,"kind":"night","imp":2,"text":"Hazel's ghost story on floor 2 of Frostspire ends with \"...and it was standing right behind them.\" Rook does not look behind her once, all night.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire"},{"id":"e2017","day":57,"season":2,"sday":27,"kind":"meet","imp":2,"text":"The Gravediggers of Ironhaven and Tobias share a fire in Frostspire. Nobody draws steel, which counts as a good meeting these days.","heroes":["h8","h15","h2","h11","h6"],"parties":["p2"],"loc":"frostspire"},{"id":"e2018","day":57,"season":2,"sday":27,"kind":"talent","imp":2,"text":"Quill finds moonpetal growing in a crack at Frostspire, glowing faintly. It's worth more than the fight was. Herbalism: one of the things Quill learned the long way round.","heroes":["h11"],"parties":["p2"],"loc":"frostspire","skill":"herbalism"},{"id":"e2041","day":58,"season":2,"sday":28,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of Frostspire at a push pace: 1 room (the draught hole).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","pace":"push","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2042","day":58,"season":2,"sday":28,"kind":"delve_done","imp":3,"text":"The Gravediggers of Ironhaven come out into the light after 7 days with the dark still in every seam. They turned up the lens hall, the yeti's empty pot, the footstool hoard and 6 more good rooms, got down to floor 2, cleared 22 rooms, inked 38% of the map, split 371 silver on the way up and turned back because the way on beat them twice, and they mean to come back with more. Frostspire, all crews together: partly explored (36%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire","days":7,"bottom":false,"rooms":["the lens hall","the yeti's empty pot"],"gold":371,"turn":"blocked"},{"id":"e2051","day":58,"season":2,"sday":28,"kind":"boss_race","imp":2,"text":"The Gravediggers of Ironhaven drop out of the race for Hrimnir, Who Walks Under Snow. That leaves Tobias and Azure Edge in it.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"frostspire"},{"id":"e2070","day":59,"season":2,"sday":29,"kind":"road","imp":3,"text":"An old pilgrim at the Snow Lamp tells Quill that the flame was lit by the first traveller to cross this pass, and has never gone out since. Quill leaves 2 copper to keep it.","heroes":["h11","h15","h2","h8"],"parties":["p2"],"road":"frostspire~whitepeak","road_rec":"r404"},{"id":"e2082","day":59,"season":2,"sday":29,"kind":"talent","imp":1,"text":"Rook drizzles a small cloud over a dry hedgerow near Whitepeak Pass. By evening there is fresh sorrel and wild garlic to pick.","heroes":["h15"],"parties":["p2"],"loc":"whitepeak","skill":"rain_on_the_fields"},{"id":"e2100","day":60,"season":2,"sday":30,"kind":"party_life","imp":1,"text":"Rook and Quill ask Hazel and Sela if the view is nice up there. It is.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"whitepeak"},{"id":"e2107","day":60,"season":2,"sday":30,"kind":"talent","imp":2,"text":"A Frosthold table argues fire against ice. Rook settles it with a small, loud storm.","heroes":["h15"],"parties":["p2"],"loc":"frosthold","skill":"all_three_at_once"},{"id":"e2108","day":60,"season":2,"sday":30,"kind":"talent","imp":1,"text":"Sela spends the afternoon in a Frosthold archive and comes out knowing why the bridge is crooked. (Walking Library, if anyone's asking.)","heroes":["h2"],"parties":["p2"],"loc":"frosthold","skill":"walking_library"},{"id":"e2111","day":60,"season":2,"sday":30,"kind":"campfire","imp":2,"text":"Hazel steadies Rook's nerves before the descent. \"We go together. We come back together.\"","heroes":["h8","h15"],"parties":["p2"],"loc":"frosthold"},{"id":"e2122","day":60,"season":2,"sday":30,"kind":"season_end","imp":5,"text":"Season 2 ends. Hazel is Hero of the Season with 356 renown. The Gravediggers of Ironhaven finish as the top party.","heroes":["h8","h15","h2","h11"],"parties":["p2"]},{"id":"e2123","day":60,"season":2,"sday":30,"kind":"top_party","imp":4,"text":"TOP PARTY: The Gravediggers of Ironhaven (Hazel, Rook, Sela and Quill) end season 2 as the league's best crew, 528 party renown. Their season: 1 boss, 10 fights won and 6 floors explored.","heroes":["h8","h15","h2","h11"],"parties":["p2"]},{"id":"e2153","day":61,"season":3,"sday":1,"kind":"bounty","imp":2,"text":"The guild clerk in Veldrock counts out bounties for The Gravediggers of Ironhaven until the cashbox is empty: 64 silver each.","heroes":["h8"],"parties":["p2"],"loc":"veldrock","amount":64},{"id":"e2158","day":61,"season":3,"sday":1,"kind":"party_life","imp":1,"text":"By the third crossroads Hazel and Sela have stopped waiting and started complaining about the wait.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"veldrock"},{"id":"e2159","day":61,"season":3,"sday":1,"kind":"road","imp":4,"text":"Osk has retired. He burns the ledger at the roadside in front of Quill and admits his real name. It is still Osk.","heroes":["h11","h15","h2","h8"],"parties":["p2"],"road":"saltmarrow~veldrock","traveller":"osk","road_rec":"r428"},{"id":"e2165","day":61,"season":3,"sday":1,"kind":"talent","imp":1,"text":"Quill stops at a wayside grave to say the words for a stranger. It takes a minute. It matters.","heroes":["h11"],"parties":["p2"],"loc":"veldrock","skill":"vigil"},{"id":"e2168","day":61,"season":3,"sday":1,"kind":"talent","imp":1,"text":"Hazel walks first down the narrow stretch, hands wide, whistling. The ambush waiting there thinks better of it.","heroes":["h8"],"parties":["p2"],"loc":"veldrock","skill":"gambit"},{"id":"e2198","day":62,"season":3,"sday":2,"kind":"campfire","imp":1,"text":"Rook and Hazel trade war stories at The Drowned Gull until the fire burns down.","heroes":["h15","h8"],"parties":["p2"],"loc":"saltmarrow"},{"id":"e2223","day":64,"season":3,"sday":4,"kind":"road","imp":3,"text":"Ambrose Nimble teaches Hazel three signs that a dealer is cheating, and one more that proves the dealer is just unlucky.","heroes":["h8","h11","h15","h2"],"parties":["p2"],"road":"saltcliffs~sunken_vault","traveller":"nimble","road_rec":"r450"},{"id":"e2253","day":65,"season":3,"sday":5,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into the Sunken Vault, mostly unexplored (17%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e2254","day":65,"season":3,"sday":5,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of the Sunken Vault at a steady pace: 3 rooms (the wrack line, a sealed space off the wrack line, the customs shed).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":3,"size":4,"floor":1,"traps":0,"sprung":1,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["cosmetic"],"fears":0,"wild":[]}},{"id":"e2293","day":66,"season":3,"sday":6,"kind":"ambush","imp":2,"text":"The Gravediggers of Ironhaven defeat 3 Bounty Hunters and the Bounty Hunters' Captain in the Sunken Vault, sent for the price on Hazel's head. Rook finished it with All Three at Once, barely looking. Sela accounted for 3 of them, mostly with Arcane Torrent. Hazel went in first, as usual. Loot: 28 silver each, 8 stolen goods, 1 gem. Rook hates deep water more than anything, and fights through it anyway.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f158","foes":["bandit_captain","bandit","bandit"],"where":"in The Sunken Vault, sent for the price on Hazel's head","won":true,"close":false,"shape":"plain"},{"id":"e2294","day":66,"season":3,"sday":6,"kind":"gear","imp":1,"text":"In a hidden room behind the customs shed on floor 1 of the Sunken Vault, Quill finds a Salt-Hardened Copper Band and puts it on. Salt-Hardened: tougher (+4% health).","heroes":["h11"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e2295","day":66,"season":3,"sday":6,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of the Sunken Vault at a steady pace: 4 rooms (a hidden room behind the customs shed, the weigh-house, the vault corridor and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":4,"floor":2,"traps":2,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":1,"wild":[]}},{"id":"e2300","day":66,"season":3,"sday":6,"kind":"bond","imp":3,"text":"The Lantern of Carrbridge and The Gravediggers of Ironhaven are rivals now, starting with Ash and Sela.","heroes":["h12","h2"],"parties":["p1","p2"],"bond":"rivals"},{"id":"e2325","day":67,"season":3,"sday":7,"kind":"wild_room","imp":3,"text":"Rook and Sela failed to turn two keys at once in the Sunken Vault. Each blames the other's counting.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","room":"wild_two_key_strongroom"},{"id":"e2326","day":67,"season":3,"sday":7,"kind":"fight","imp":2,"text":"The Gravediggers of Ironhaven, in fine spirits lately, beat 5 Drowned in the counting-house on floor 2 of the Sunken Vault. Sela ended it with Banishing Rite. Loot: 27 trinkets, 12 barnacle oysters, 8 remains.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f160","foes":["drowned","drowned","drowned"],"where":"in the counting-house on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"mood","reworded":-25},{"id":"e2327","day":67,"season":3,"sday":7,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of the Sunken Vault at a push pace: 5 rooms (the silted atrium, the two-key strongroom, the ledger archive and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"push","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":2,"wild":["wild_two_key_strongroom"]}},{"id":"e2354","day":68,"season":3,"sday":8,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of the Sunken Vault at a push pace: 5 rooms (the deposit boxes, the night-chute, the paymaster's quarters and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"push","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e2398","day":69,"season":3,"sday":9,"kind":"fight","imp":2,"text":"Three Drowned fall to the Gravediggers of Ironhaven in the drill yard on floor 2 of the Sunken Vault. Quill closed it out with Arc Lightning on the Drowned. Loot: 4 remains, 4 trinkets, 4 barnacle oysters.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f166","foes":["drowned","drowned","drowned"],"where":"in the drill yard on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"foe","reworded":-3,"wx":"storm"},{"id":"e2401","day":69,"season":3,"sday":9,"kind":"fight","imp":2,"text":"In a drowned staircase with a brass handrail on floor 2 of the Sunken Vault, the Gravediggers of Ironhaven handle 4 Sirens. The siren took Sela's Arcane Torrent full on and was never the same after. Loot: 8 sea grapes, 1 gem, 5 trinkets.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f167","foes":["siren","siren","siren"],"where":"in a drowned staircase with a brass handrail on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-1,"wx":"storm"},{"id":"e2402","day":69,"season":3,"sday":9,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of the Sunken Vault at a steady pace: 5 rooms (the diving-bell chamber, the drill yard, a drowned staircase with a brass handrail and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":5,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":2,"close":0,"gear":[],"fears":4,"wild":[]},"wx":"storm"},{"id":"e2408","day":69,"season":3,"sday":9,"kind":"talent","imp":1,"text":"Sela knows from a footnote that the third stair creaks. It does. Nobody steps on it. Chalk it up to Seen It in a Book.","heroes":["h2"],"parties":["p2"],"loc":"sunken_vault","skill":"seen_it_in_a_book","wx":"storm"},{"id":"e2409","day":69,"season":3,"sday":9,"kind":"ability","imp":2,"text":"Sela finds a mouldering book in the Sunken Vault, sits on a skeleton's chair and reads it cover to cover. Hazel keeps watch and is told the plot whether they like it or not.","heroes":["h2","h8"],"parties":["p2"],"loc":"sunken_vault","skill":"walking_library","sk":"Walking Library","rule":true,"wx":"storm"},{"id":"e2430","day":70,"season":3,"sday":10,"kind":"fight","imp":2,"text":"Rook hits hardest as the Gravediggers of Ironhaven defeat 5 Drowned in the queue for teller nine on floor 2 of the Sunken Vault. Hazel ended it the plain way: Hammer Down, and the Drowned on the ground. Rook accounted for 3 of them, mostly with Sudden Monsoon. Loot: 13 barnacle oysters, 21 trinkets.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f169","foes":["drowned","drowned","drowned"],"where":"in the queue for teller nine on floor 2 of the Sunken Vault","won":true,"close":false,"shape":"hero","reworded":-21},{"id":"e2431","day":70,"season":3,"sday":10,"kind":"fight","imp":2,"text":"The Gravediggers of Ironhaven get the better of 4 Drowned in the guards' barracks on floor 3 of the Sunken Vault. The fight was over the moment Rook's Banishing Rite landed on the Drowned. Ask the others what won it: Hazel's Cavalry Drill. Loot: 23 trinkets, 15 barnacle oysters.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f170","foes":["drowned","drowned","drowned"],"where":"in the guards' barracks on floor 3 of the Sunken Vault","won":true,"close":false,"shape":"plain","reworded":-10},{"id":"e2432","day":70,"season":3,"sday":10,"kind":"gear","imp":1,"text":"In a sealed space off the guards' barracks on floor 3 of the Sunken Vault, Hazel finds a Quick Shadowweave Hood and puts it on. Quicker (+0.8 speed).","heroes":["h8"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e2433","day":70,"season":3,"sday":10,"kind":"wild_room","imp":3,"text":"Rook's fear of water finds a dry stair in the Sunken Vault. Rook: 'I've been saying this for years.'","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","room":"wild_cowards_stair"},{"id":"e2434","day":70,"season":3,"sday":10,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 3 of the Sunken Vault at a steady pace: 4 rooms (the queue for teller nine, the guards' barracks, a sealed space off the guards' barracks and 1 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":4,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":0,"fights":2,"close":0,"gear":["great"],"fears":3,"wild":["wild_cowards_stair"]}},{"id":"e2452","day":71,"season":3,"sday":11,"kind":"wild_room","imp":3,"text":"The Sunken Vault siren has a regular card night now. Thursdays. Sela brings the snacks.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","room":"wild_tide_cards"},{"id":"e2453","day":71,"season":3,"sday":11,"kind":"gear","imp":1,"text":"In the sleeping cells on floor 3 of the Sunken Vault, Sela finds a pair of Quick Soft-Soled Boots and puts them on. Quicker (+0.8 speed).","heroes":["h2"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e2454","day":71,"season":3,"sday":11,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 3 of the Sunken Vault at a steady pace: 5 rooms (a hidden room behind the smugglers' dry stair, the siren's card table, the sleeping cells and 2 more).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":5,"size":4,"floor":3,"traps":1,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":["great"],"fears":1,"wild":["wild_tide_cards"]}},{"id":"e2482","day":71,"season":3,"sday":11,"kind":"goal","imp":2,"text":"After a long night's talk, The Gravediggers of Ironhaven settle on a goal: to earn 600 silver between them before the season ends.","heroes":["h8","h15","h2"],"parties":["p2"]},{"id":"e2503","day":72,"season":3,"sday":12,"kind":"delve_done","imp":3,"text":"The Gravediggers of Ironhaven climb the last ladder after 8 days, and the sitting down happens at the top of it. They disarmed 1 trap, got down to floor 3, cleared 31 rooms, mapped 52% of it, turned up the wrack line, a sealed space off the wrack line, a hidden room behind the customs shed and 11 more good rooms, came away with 790 silver between them and turned back because their nerves were fraying. Between every crew so far, the Sunken Vault is partly explored (49%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","days":8,"bottom":false,"rooms":["the wrack line","a sealed space off the wrack line"],"gold":790,"turn":"nerve"},{"id":"e2504","day":72,"season":3,"sday":12,"kind":"night","imp":2,"text":"Rook trades a ration with a stranger who wasn't there at dusk and isn't there at dawn. The trinket stays.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e2518","day":72,"season":3,"sday":12,"kind":"talent","imp":1,"text":"Rook fogs a corridor so the goblin on guard never sees her slip past. That's Pea-Souper for you.","heroes":["h15"],"parties":["p2"],"loc":"sunken_vault","skill":"pea_souper"},{"id":"e2522","day":72,"season":3,"sday":12,"kind":"argument","imp":2,"text":"It starts with Rook's snoring. It ends with Rook and Sela sleeping on opposite sides of the fire.","heroes":["h15","h2"],"parties":["p2"]},{"id":"e2528","day":73,"season":3,"sday":13,"kind":"party_life","imp":3,"text":"Rook and Quill arrive at camp an hour behind Hazel and Sela and find the good spot by the fire taken.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","wx":"fog"},{"id":"e2568","day":74,"season":3,"sday":14,"kind":"party_life","imp":1,"text":"Hazel and Sela wait at every crossroads for Rook and Quill to catch up, and say nothing very loudly.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"saltcliffs","wx":"storm"},{"id":"e2578","day":74,"season":3,"sday":14,"kind":"goal_done","imp":4,"text":"The Gravediggers of Ironhaven can cross it off: earn 600 silver between them before the season ends. Drinks are on them. XP: Hazel +800 (level 21!), Rook +800, Sela +968, Quill +919.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"xp":{"h8":800,"h15":800,"h2":968,"h11":919}},{"id":"e2582","day":74,"season":3,"sday":14,"kind":"big_move","imp":3,"text":"The Gravediggers of Ironhaven can cross it off: earn 600 silver between them before the season ends. On the table: Quill +71 renown (holds 5th) and Hazel +54 (holds 6th). The Gravediggers of Ironhaven +56 party renown (holds 2nd among the crews).","heroes":["h11","h8"],"parties":["p2"],"cause":"e2578","moves":[{"hero":"h11","gain":71,"from":5,"to":5},{"hero":"h8","gain":54,"from":6,"to":6}],"party_moves":[{"party":"p2","gain":56,"from":2,"to":2}]},{"id":"e2599","day":75,"season":3,"sday":15,"kind":"road","imp":3,"text":"Pim tells Hazel the whole story of leaving the bakery. Hazel listens like a master and advises like one, too.","heroes":["h8","h11","h15","h2"],"parties":["p2"],"road":"carrbridge~saltmarrow","traveller":"pim","road_rec":"r501"},{"id":"e2612","day":75,"season":3,"sday":15,"kind":"talent","imp":2,"text":"Quill pulls a handful of yarrow from a field edge and stuffs it in a pouch. 'For later. You'll see.'","heroes":["h11"],"parties":["p2"],"loc":"saltmarrow","skill":"herbalism","wx":"storm"},{"id":"e2618","day":75,"season":3,"sday":15,"kind":"campfire","imp":2,"text":"Hazel and Sela invent a scoring system for snoring. Nobody else is consulted.","heroes":["h8","h2"],"parties":["p2"],"loc":"saltmarrow","wx":"storm"},{"id":"e2645","day":76,"season":3,"sday":16,"kind":"bounty","imp":2,"text":"The Gravediggers of Ironhaven cash in a season's worth of trophies at the Carrbridge guild: about 97 silver a head.","heroes":["h8"],"parties":["p2"],"loc":"carrbridge","amount":97,"wx":"fog"},{"id":"e2655","day":76,"season":3,"sday":16,"kind":"talent","imp":1,"text":"Quill sells a bundle of dried herbs to the Carrbridge apothecary, with a short lecture on drying them properly.","heroes":["h11"],"parties":["p2"],"loc":"carrbridge","skill":"herbalism","wx":"fog"},{"id":"e2686","day":77,"season":3,"sday":17,"kind":"boss_race","imp":3,"text":"Cindervast the Hoardmother has visitors coming. The Gravediggers of Ironhaven and Cobalt Mercy are both on the way to Emberdeep, and nobody is waiting for the others.","heroes":["h8","h15","h2","h11","h19","h20"],"parties":["p2","p6"],"loc":"emberdeep"},{"id":"e2692","day":77,"season":3,"sday":17,"kind":"argument","imp":1,"text":"Rook and Hazel of The Gravediggers of Ironhaven have a shouting match about who ate the last of the cheese.","heroes":["h15","h8"],"parties":["p2"]},{"id":"e2693","day":77,"season":3,"sday":17,"kind":"campfire","imp":1,"text":"Sela reads aloud while Rook sharpens blades, and neither wants the chapter to end.","heroes":["h2","h15"],"parties":["p2"],"loc":"ironhaven","wx":"fog"},{"id":"e2740","day":79,"season":3,"sday":19,"kind":"talent","imp":1,"text":"Sela practises a magistrate's signature by firelight until it's better than the magistrate's.","heroes":["h2"],"parties":["p2"],"loc":"emberdeep","skill":"forgery","wx":"storm"},{"id":"e2745","day":79,"season":3,"sday":19,"kind":"meet","imp":2,"text":"Sela and Wren swap stories in Emberdeep while The Gravediggers of Ironhaven and Cobalt Mercy swap rumours.","heroes":["h8","h15","h2","h11","h19","h20"],"parties":["p2","p6"],"loc":"emberdeep","wx":"storm"},{"id":"e2746","day":79,"season":3,"sday":19,"kind":"gift","imp":2,"text":"The Third-Place Ribbon changes hands again: Quill to Hazel this time. It has been passed around this crew 2 times now.","heroes":["h11","h8"],"parties":["p2"],"loc":"emberdeep","wx":"storm"},{"id":"e2748","day":79,"season":3,"sday":19,"kind":"ability","imp":2,"text":"Sela lies on their back in Emberdeep to copy a painting on the ceiling, neck cricked, perfectly content. It turns out to be a star chart, and they learn a great deal from it.","heroes":["h2"],"parties":["p2"],"loc":"emberdeep","skill":"walking_library","sk":"Walking Library","rule":true,"wx":"storm"},{"id":"e2755","day":79,"season":3,"sday":19,"kind":"campfire","imp":1,"text":"Quill fans Rook with a dwarven shield until Rook stops complaining about the heat, which takes an hour.","heroes":["h11","h15"],"parties":["p2"],"loc":"emberdeep","wx":"storm"},{"id":"e2764","day":80,"season":3,"sday":20,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into Emberdeep, mostly unexplored (28%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"emberdeep","wx":"storm"},{"id":"e2765","day":80,"season":3,"sday":20,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 1 of Emberdeep at a steady pace: 3 rooms (the wall of songs, the crucible gallery, a sealed space off the crucible gallery).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"emberdeep","pace":"steady","stats":{"rooms":3,"size":4,"floor":1,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e2766","day":80,"season":3,"sday":20,"kind":"talent","imp":2,"text":"Rook rolls a low mist over the camp at dawn. Sela says it's beautiful, then trips over a tent rope.","heroes":["h15","h2"],"parties":["p2"],"loc":"emberdeep","skill":"pea_souper","wx":"storm"},{"id":"e2798","day":81,"season":3,"sday":21,"kind":"fight","imp":3,"text":"Three Fire Elementals and a Salamander are too much for the Gravediggers of Ironhaven in the dwarven great hall on floor 2 of Emberdeep, and it's time to run for it. Rook hasn't said a word since. Injured: Rook (bruised ribs). For Hazel, it was always going to be fire.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"emberdeep","fight":"f188","foes":["salamander","fire_elemental","fire_elemental"],"where":"in the dwarven great hall on floor 2 of Emberdeep","won":false,"close":true,"shape":"foe","reworded":-21,"wx":"storm"},{"id":"e2799","day":81,"season":3,"sday":21,"kind":"vow_broken","imp":4,"text":"VOW BROKEN. On day 1 of season 2, The Gravediggers of Ironhaven swore never to retreat. Today they ran from a fight.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"cause":"e1109"},{"id":"e2800","day":81,"season":3,"sday":21,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of Emberdeep at a push pace: 1 room (the dwarven great hall).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"emberdeep","pace":"push","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":1,"unwalked":1,"fights":1,"close":1,"gear":[],"fears":2,"wild":[]},"wx":"storm"},{"id":"e2801","day":81,"season":3,"sday":21,"kind":"delve_done","imp":1,"text":"After 2 days and one bad fight, The Gravediggers of Ironhaven climb out, calling it a retreat with dignity. They reached floor 2, came across a sealed space off the crucible gallery, worked through 3 rooms, put 8% of it on paper and split 80 silver on the way up. Add up every party's sketches and Emberdeep comes out mostly unexplored (32%).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"emberdeep","days":2,"bottom":false,"rooms":["a sealed space off the crucible gallery"],"gold":80,"out":"Driven out","turn":"routed","wx":"storm"},{"id":"e2818","day":81,"season":3,"sday":21,"kind":"boss_race","imp":2,"text":"The Gravediggers of Ironhaven give up on Cindervast the Hoardmother for now, and the race to Emberdeep belongs to Cobalt Mercy.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"emberdeep","wx":"storm"},{"id":"e2823","day":81,"season":3,"sday":21,"kind":"campfire","imp":1,"text":"Rook and Hazel find a pear tree by the road and eat far more than is wise.","heroes":["h15","h8"],"parties":["p2"],"loc":"emberdeep","wx":"storm"},{"id":"e2829","day":81,"season":3,"sday":21,"kind":"ledger","imp":2,"text":"THE LEDGER: 26 hauls sold this week, 1,976 silver in all. Biggest haul: Barnaby, 234 silver in Veldrock. Back up from the deep: Azure Edge (2 days in Frostspire), The White Quills (2 days in the Ashveil Crypts), The Gravediggers of Ironhaven (2 days in Emberdeep).","heroes":["h19","h3","h7","h8"],"parties":["p3","p5","p2"]},{"id":"e2849","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"A Veldrock tavern fills with a mysterious fog whenever someone asks Rook to sing. They stop asking. Chalk it up to Pea-Souper.","heroes":["h15"],"parties":["p2"],"loc":"veldrock","skill":"pea_souper","wx":"storm"},{"id":"e2852","day":82,"season":3,"sday":22,"kind":"talent","imp":1,"text":"Sela presents a letter of introduction in Veldrock from a duke who has never heard of her. It works. Somebody asks how. 'Forgery,' says Sela.","heroes":["h2"],"parties":["p2"],"loc":"veldrock","skill":"forgery","wx":"storm"},{"id":"e2874","day":83,"season":3,"sday":23,"kind":"road","imp":3,"text":"In payment for the lifting, Hjalmar hands Sela a lump of ore from the bottom of an ore sack. 'Good for a pocket,' says the dwarf.","heroes":["h2","h11","h15","h8"],"parties":["p2"],"road":"ironhaven~veldrock","traveller":"deepvein","road_rec":"r567"},{"id":"e2888","day":83,"season":3,"sday":23,"kind":"talent","imp":2,"text":"An Ironhaven locksmith asks Hazel how it's done. Hazel makes a small bang gesture. The locksmith leaves. (Blast the Lock, if anyone's asking.)","heroes":["h8"],"parties":["p2"],"loc":"ironhaven","skill":"blast_the_lock"},{"id":"e2910","day":84,"season":3,"sday":24,"kind":"road","imp":3,"text":"Scratched on the lowest of the Four Stones is a crude map of all four roads and a mark that says treasure. Sela copies it carefully, and finds 9 silver under the marked pebble.","heroes":["h2","h11","h15","h8"],"parties":["p2"],"road":"carrbridge~ironhaven","road_rec":"r570"},{"id":"e2924","day":84,"season":3,"sday":24,"kind":"talent","imp":1,"text":"Quill preaches on a crate in the Carrbridge square. Half the crowd stays to the end, which is a good half. Sermon, cast gently, for once.","heroes":["h11"],"parties":["p2"],"loc":"carrbridge","skill":"sermon"},{"id":"e2944","day":85,"season":3,"sday":25,"kind":"party_life","imp":1,"text":"Rook and Quill ask Hazel and Sela if the view is nice up there. It is.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"carrbridge"},{"id":"e2947","day":85,"season":3,"sday":25,"kind":"ambush","imp":2,"text":"Rook hits hardest as the Gravediggers of Ironhaven handle a Wolf, a Bandit and a Bandit Captain at their camp on the road to Saltmarrow, in the middle of the night. The fight was over the moment Sela's Banishing Rite landed on the bandit captain. Rook kept two of them busy so nobody else had to. Sela went in first, as usual. Loot: 13 silver each, 2 rations, 5 stolen goods.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"kingsroad","fight":"f203","foes":["wolf","bandit","bandit_captain"],"where":"at their camp on the road to Saltmarrow, in the middle of the night","won":true,"close":false,"shape":"hero","reworded":-21},{"id":"e2963","day":85,"season":3,"sday":25,"kind":"talent","imp":1,"text":"Quill asks a bramble patch to let the party through. It thinks about it, then does. Quill puts it down to Rootbound Ground.","heroes":["h11"],"parties":["p2"],"loc":"carrbridge","skill":"rootbound_ground"},{"id":"e2965","day":85,"season":3,"sday":25,"kind":"campfire","imp":1,"text":"Rook patches Sela's cloak without being asked. Sela pretends not to notice, then says thanks.","heroes":["h2","h15"],"parties":["p2"],"loc":"carrbridge"},{"id":"e2966","day":85,"season":3,"sday":25,"kind":"ability","imp":2,"text":"Sela chalks a troll's insides on a flat stone and makes the crew point to the soft bits. Marks are given. Nobody gets full marks.","heroes":["h2"],"parties":["p2"],"loc":"carrbridge","skill":"tutor","sk":"Tutor","rule":true},{"id":"e2999","day":86,"season":3,"sday":26,"kind":"talent","imp":2,"text":"Hazel stakes a month's boots on the first throw at a Saltmarrow table and wins them back, plus a second pair.","heroes":["h8"],"parties":["p2"],"loc":"saltmarrow","skill":"gambit","wx":"fog"},{"id":"e3035","day":87,"season":3,"sday":27,"kind":"party_life","imp":1,"text":"By the third crossroads Hazel and Sela have stopped waiting and started complaining about the wait.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"saltmarrow","wx":"fog"},{"id":"e3071","day":88,"season":3,"sday":28,"kind":"party_life","imp":1,"text":"Rook and Quill spend the whole road in the dust Hazel and Sela kick up, and say so.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"saltcliffs","wx":"fog"},{"id":"e3084","day":88,"season":3,"sday":28,"kind":"talent","imp":1,"text":"Hazel measures a pinch of powder as carefully as a baker measures spice.","heroes":["h8"],"parties":["p2"],"loc":"sunken_vault","skill":"blast_the_lock","wx":"fog"},{"id":"e3101","day":89,"season":3,"sday":29,"kind":"delve","imp":1,"text":"The Gravediggers of Ironhaven descend into the Sunken Vault, mostly explored (66%), map in hand.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault"},{"id":"e3102","day":89,"season":3,"sday":29,"kind":"fight","imp":1,"text":"In the sea stairs, green to the waterline on floor 1 of the Sunken Vault, 2 Sirens and a Cliff Crab get in the Gravediggers of Ironhaven's way, briefly. The last cliff crab doesn't stay to see the end. Sela picked out the siren and finished the job with Drain Life. Ask the others what won it: Quill's Awaken the Grove. Loot: 3 trinkets. Rook, who has been afraid of deep water since childhood, does not run. Nobody says anything. Everybody noticed.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","fight":"f215","foes":["siren","siren","crab"],"where":"in the sea stairs, green to the waterline on floor 1 of the Sunken Vault","won":true,"close":false,"shape":"place","reworded":-37},{"id":"e3103","day":89,"season":3,"sday":29,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 2 of the Sunken Vault at a steady pace: 1 room (the sea stairs, green to the waterline).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"steady","stats":{"rooms":1,"size":4,"floor":2,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":1,"close":0,"gear":[],"fears":1,"wild":[]}},{"id":"e3121","day":89,"season":3,"sday":29,"kind":"talent","imp":2,"text":"Sela lectures Rook on wolf behaviour while three wolves watch from the treeline, taking notes. That's Seen It in a Book for you.","heroes":["h2","h15"],"parties":["p2"],"loc":"sunken_vault","skill":"seen_it_in_a_book"},{"id":"e3125","day":90,"season":3,"sday":30,"kind":"delve_day","imp":1,"text":"The Gravediggers of Ironhaven work floor 3 of the Sunken Vault at a push pace: 1 room (the bullion ramp, slick with weed).","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","pace":"push","stats":{"rooms":1,"size":4,"floor":3,"traps":0,"sprung":0,"trap_inj":0,"uncleared":0,"unwalked":0,"fights":0,"close":0,"gear":[],"fears":0,"wild":[]}},{"id":"e3156","day":90,"season":3,"sday":30,"kind":"delve_done","imp":1,"text":"The Sunken Vault, 2 days on: The Gravediggers of Ironhaven come up blinking at the daylight. They took 2 rooms off the map's blank side and reached floor 3.","heroes":["h8","h15","h2","h11"],"parties":["p2"],"loc":"sunken_vault","days":2,"bottom":false,"rooms":[],"gold":0}],"roles":{"h2":"Spellcaster","h8":"Leader · Quartermaster","h11":"Tracker","h15":"Scout"},"quest":{"what":"Delve","where":"The Sunken Vault","why":"chasing a rumour: about 58 silver a day each, risk slight","floor":2,"floors":4},"tactics":{"front":["h8"],"back":["h15","h2","h11"],"plan":"Hazel holds the front; Rook, Sela and Quill cast from behind; Quill keeps everyone standing.","traits":{"boldness":0.43,"risk":0.13,"greed":-0.07,"sociability":0.04,"honor":-0.17,"curiosity":0.08,"temper":-0.07,"loyalty":0.07},"mix":"3 casters, 1 blade","notes":["One shield. If Hazel falls, the line goes with her.","Spell-heavy: they win fast or not at all."],"style":["bold","spell-heavy"],"skills":[{"label":"Damage","skills":[{"hero":"h2","id":"arcane_torrent","name":"Arcane Torrent","desc":"Opens the book and lets it out.","tags":["arcane"],"rank":1,"uses":20},{"hero":"h11","id":"arc_lightning","name":"Arc Lightning","desc":"Jumps between targets. Hair stands up.","tags":["storm"],"rank":2,"uses":19},{"hero":"h15","id":"all_three_at_once","name":"All Three at Once","desc":"Can't choose a favourite. Throws them all.","tags":[],"rank":1,"uses":17},{"hero":"h15","id":"spark_storm","name":"Spark Storm","desc":"Showy. Effective. Smells of ozone.","tags":["storm","fire"],"rank":3,"uses":11},{"hero":"h15","id":"force_bolt","name":"Force Bolt","desc":"An invisible fist, thrown from across the room.","tags":["arcane"],"rank":3,"uses":11},{"hero":"h2","id":"banishing_rite","name":"Banishing Rite","desc":"Reads the old words. Spirits hate the old words.","tags":["holy","arcane"],"rank":2,"uses":11},{"hero":"h2","id":"chill_touch","name":"Chill Touch","desc":"A grave-cold hand on the shoulder.","tags":["death"],"rank":1,"uses":11},{"hero":"h2","id":"drain_life","name":"Drain Life","desc":"Their loss, literally your gain.","tags":["death","heal"],"rank":1,"uses":8},{"hero":"h8","id":"anvil_drop","name":"Anvil Drop","desc":"Brought the anvil. Nobody asked why. Now they know.","tags":["craft"],"rank":2,"uses":5},{"hero":"h15","id":"banishing_rite","name":"Banishing Rite","desc":"Reads the old words. Spirits hate the old words.","tags":["holy","arcane"],"rank":2,"uses":4},{"hero":"h8","id":"blasting_powder","name":"Blasting Powder","desc":"A pouch, a fuse, a short run.","tags":["craft","fire"],"rank":2,"uses":2},{"hero":"h15","id":"lightning_bolt","name":"Lightning Bolt","desc":"Straight through the armour, smelling of rain.","tags":["storm"],"rank":1,"uses":2},{"hero":"h15","id":"sudden_monsoon","name":"Sudden Monsoon","desc":"Floods the field. Mostly the goblins' half.","tags":["nature","storm"],"rank":1,"uses":2},{"hero":"h8","id":"hammer_down","name":"Hammer Down","desc":"Forging technique, applied to faces.","tags":["craft"],"rank":1,"uses":1},{"hero":"h15","id":"expose_weakness","name":"Expose Weakness","desc":"Points out the soft bit, loudly.","tags":["lore","crit"],"rank":1,"uses":0},{"hero":"h15","id":"chain_lightning","name":"Chain Lightning","desc":"Arcs through the whole crowd.","tags":["storm"],"rank":1,"uses":0}]},{"label":"Healing","skills":[{"hero":"h11","id":"first_aid","name":"First Aid","desc":"Knows which end of a bandage goes where.","tags":["heal"],"rank":2,"uses":4}]},{"label":"Defence","skills":[{"hero":"h8","id":"gambit","name":"Gambit","desc":"Opens by giving something up. Always meant to.","tags":[],"rank":1,"uses":19},{"hero":"h8","id":"hold_the_line","name":"Hold the Line","desc":"Nobody steps back. Nobody.","tags":["guard","command"],"rank":2,"uses":11},{"hero":"h11","id":"barkskin","name":"Barkskin","desc":"Skin goes knotted and brown. It's fine. It's fine.","tags":["nature","guard"],"rank":2,"uses":10},{"hero":"h8","id":"shore_up","name":"Shore Up","desc":"Bangs a dent out of everyone's armour mid-fight.","tags":["craft","guard"],"rank":2,"uses":0}]},{"label":"Tricks","skills":[{"hero":"h8","id":"cavalry_drill","name":"Cavalry Drill","desc":"Calls the line into order before the first blow.","tags":["ride"],"rank":1,"uses":28},{"hero":"h11","id":"entangle","name":"Entangle","desc":"Roots burst from the floor.","tags":["nature"],"rank":2,"uses":14},{"hero":"h11","id":"awaken_the_grove","name":"Awaken the Grove","desc":"The trees were only waiting to be asked.","tags":["nature"],"rank":1,"uses":9},{"hero":"h15","id":"sleet_squall","name":"Sleet Squall","desc":"Freezing rain on every foe.","tags":["ice","storm"],"rank":1,"uses":3},{"hero":"h15","id":"entangle","name":"Entangle","desc":"Roots burst from the floor.","tags":["nature"],"rank":2,"uses":3},{"hero":"h11","id":"rootbound_ground","name":"Rootbound Ground","desc":"Outnumbered is just a word for more ankles.","tags":[],"rank":1,"uses":3},{"hero":"h8","id":"captains_call","name":"Captain's Call","desc":"When one falls, the rest hit harder for them.","tags":["command","rage"],"rank":1,"uses":2},{"hero":"h2","id":"seen_it_in_a_book","name":"Seen It in a Book","desc":"Knows what a goblin warband does next. Read about it. Took notes.","tags":[],"rank":1,"uses":2},{"hero":"h8","id":"balanced_blade","name":"Balanced Blade","desc":"Weighted it just so. The second swing is easier than the first.","tags":["crit","craft"],"rank":1,"uses":1},{"hero":"h15","id":"pea_souper","name":"Pea-Souper","desc":"Brings in a fog you could spread on toast.","tags":[],"rank":1,"uses":1},{"hero":"h11","id":"old_wood_stands","name":"The Old Wood Is Angry","desc":"Gang up on a druid and the forest takes it personally.","tags":[],"rank":1,"uses":0},{"hero":"h11","id":"phantasm","name":"Phantasm","desc":"A horror only the monster can see.","tags":["stealth"],"rank":1,"uses":0}]},{"label":"Always on","skills":[{"hero":"h2","id":"know_thy_enemy","name":"Know Thy Enemy","desc":"Read the bestiary. Twice.","tags":["lore"],"rank":2,"uses":0},{"hero":"h2","id":"lore","name":"Ancient Lore","desc":"Knows every monster's weakness from a book.","tags":["arcane","lore"],"rank":2,"uses":0},{"hero":"h2","id":"legend","name":"Living Legend","desc":"Songs are already being written.","tags":[],"rank":1,"uses":0},{"hero":"h11","id":"oakheart","name":"Oakheart","desc":"Has rings. Won't say how many.","tags":["nature"],"rank":1,"uses":0},{"hero":"h11","id":"thornskin","name":"Thornskin","desc":"Hugging is not advised.","tags":["nature"],"rank":1,"uses":0},{"hero":"h11","id":"steady_nerves","name":"Steady Nerves","desc":"Doesn't flinch. Neither does the party.","tags":["holy"],"rank":1,"uses":0}]},{"label":"On the road","skills":[{"hero":"h8","id":"bulk_trader","name":"Bulk Trader","desc":"Buys a mule. Then another.","tags":["trade","travel"],"rank":2,"uses":0},{"hero":"h8","id":"supply_master","name":"Supply Master","desc":"Gets supplies at cost.","tags":["trade"],"rank":2,"uses":0},{"hero":"h8","id":"peacemaker","name":"Peacemaker","desc":"Stops the argument before it gets to the swords.","tags":["command","holy"],"rank":1,"uses":0},{"hero":"h8","id":"trail_baker","name":"Trail Baker","desc":"Bread on the road. Actual bread.","tags":[],"rank":1,"uses":0},{"hero":"h8","id":"whetstone","name":"Whetstone","desc":"Sharpens everything. Has been asked to stop.","tags":["craft"],"rank":1,"uses":0},{"hero":"h8","id":"tea_ceremony","name":"Tea Ceremony","desc":"Nothing is so bad it can't wait for the kettle.","tags":[],"rank":1,"uses":0},{"hero":"h8","id":"rockblaster","name":"Rockblaster","desc":"Blows a hole in the hill. The road is shorter now. The hill is upset.","tags":["fire","craft"],"rank":1,"uses":0},{"hero":"h15","id":"smokehouse","name":"Smokehouse","desc":"Smoked fish, smoked sausage, smoked everything.","tags":[],"rank":1,"uses":0},{"hero":"h15","id":"freeze_over","name":"Freeze Over","desc":"Freezes the ford. Everyone walks across.","tags":["ice"],"rank":2,"uses":0},{"hero":"h15","id":"rain_on_the_fields","name":"Rain on the Fields","desc":"Waters the herb patch from a cloud they brought along.","tags":["nature","storm"],"rank":1,"uses":0},{"hero":"h15","id":"trick_shot","name":"Trick Shot","desc":"Shoots the apple off your head. Asks first.","tags":["crit"],"rank":1,"uses":0},{"hero":"h15","id":"lightning_rod","name":"Lightning Rod","desc":"Draws the strike on storm nights and sells the glass.","tags":["storm"],"rank":1,"uses":0},{"hero":"h2","id":"study","name":"Studious","desc":"Reads everything, learns faster.","tags":["lore"],"rank":3,"uses":0},{"hero":"h2","id":"grave_tender","name":"Grave Tender","desc":"Tidies forgotten graves. The dead appreciate it.","tags":["death","holy"],"rank":1,"uses":0},{"hero":"h2","id":"linguist","name":"Linguist","desc":"Speaks six languages, including Goblin, badly.","tags":["lore","arcane"],"rank":1,"uses":0},{"hero":"h2","id":"cantrips","name":"Cantrips","desc":"Small magic. Big crowds.","tags":["arcane","lore"],"rank":2,"uses":0},{"hero":"h2","id":"hand_signs","name":"Hand Signs","desc":"Can say 'goblins, three, left' without a sound.","tags":["stealth"],"rank":1,"uses":0},{"hero":"h2","id":"letter_writer","name":"Letter Writer","desc":"Writes home. Writes everyone's home.","tags":["lore"],"rank":1,"uses":0},{"hero":"h2","id":"firekeeper","name":"Firekeeper","desc":"Lights a fire in a rainstorm, with wet wood, every time.","tags":[],"rank":1,"uses":0},{"hero":"h2","id":"forgery","name":"Forgery","desc":"Their handwriting is your handwriting.","tags":["stealth","trade"],"rank":1,"uses":0},{"hero":"h11","id":"herbalism","name":"Herbalism","desc":"Knows every useful leaf.","tags":["nature","heal"],"rank":1,"uses":0},{"hero":"h11","id":"detect_magic","name":"Detect Magic","desc":"Knows a relic's worth at a glance.","tags":["arcane","trade"],"rank":1,"uses":0},{"hero":"h11","id":"charcoal_burner","name":"Charcoal Burner","desc":"Burns charcoal on rest days. The blacksmith buys every sack.","tags":["fire"],"rank":1,"uses":0},{"hero":"h11","id":"wild_tongue","name":"Wild Tongue","desc":"Asks the birds. The birds know a shortcut.","tags":["nature"],"rank":1,"uses":0},{"hero":"h11","id":"vigil","name":"Vigil","desc":"Keeps watch and prays through the small hours.","tags":["holy","guard"],"rank":1,"uses":0},{"hero":"h11","id":"fire_eater","name":"Fire Eater","desc":"Eats fire. Never orders hot soup.","tags":[],"rank":1,"uses":0},{"hero":"h11","id":"sermon","name":"Sermon","desc":"Preaches on market day. Alms, standing, the odd convert.","tags":["holy"],"rank":1,"uses":0},{"hero":"h11","id":"forest_council","name":"Forest Council","desc":"Sits with the old oaks. Learns slowly, thoroughly.","tags":["nature"],"rank":1,"uses":0}]}],"share":[{"hero":"h8","dmg":742,"healed":24,"taken":305,"kills":3,"row":"front"},{"hero":"h15","dmg":2196,"healed":0,"taken":190,"kills":11,"row":"back"},{"hero":"h2","dmg":3730,"healed":0,"taken":140,"kills":12,"row":"back"},{"hero":"h11","dmg":202,"healed":87,"taken":51,"kills":3,"row":"back"}],"ground":{"name":"The Sunken Vault","fights":7}},"trophies":[{"boss":"Mother Thornmere","monster":"hag_mother","place":"Thornmere Ruins","day":44,"season":2,"fight":"f103"}]};